def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    opp_moves = [o for _, o in history]
    my_moves = [m for m, _ in history]
    opp_def_total = opp_moves.count('D')
    my_def_total = my_moves.count('D')
    opp_coop_rate = (n - opp_def_total) / n

    # Defection streak tracking
    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if opp_moves[i] == 'D':
            opp_streak += 1
        else:
            break
    my_streak = 0
    for i in range(n - 1, -1, -1):
        if my_moves[i] == 'D':
            my_streak += 1
        else:
            break

    # Harsh punish only on sustained defection with low overall cooperativeness
    if opp_streak >= 3 and opp_coop_rate < 0.7:
        return 'D'
    if opp_def_total >= 4 and opp_coop_rate < 0.25:
        return 'D'

    # End-game: exploit known cooperators strongly, else tit-for-tat
    if n >= 90:
        if opp_coop_rate >= 0.7:
            return 'D'
        if opp_moves[-1] == 'D':
            return 'D'
        return 'C'

    # If opponent cooperated last round, cooperate -- preserve mutual cooperation
    if opp_moves[-1] == 'C':
        return 'C'

    # Opponent just defected.
    # If we defected last round too (mutual defection), take a chance and forgive.
    if my_moves[-1] == 'D':
        if rng.random() < 0.55:
            return 'C'
        return 'D'

    # We cooperated, opponent defected (we were suckered).
    # Retaliate once, but not into a permanent spiral.
    if opp_streak == 1:
        return 'D'
    if rng.random() < 0.5:
        return 'C'
    return 'D'
